using ContosoUniversity;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "A", "B", "C" };

        // Act
        var list = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, list.Count);
        Assert.Equal("A", list[0]);
        Assert.Equal("B", list[1]);
        Assert.Equal("C", list[2]);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_WhenCountDivisibleByPageSize()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
        Assert.Equal(2, list.TotalPages); // 10/5 = 2 exactly
    }

    [Fact]
    public void TotalPages_RoundsUp_WhenCountNotDivisibleByPageSize()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 11, 1, 5);
        Assert.Equal(3, list.TotalPages); // ceil(11/5) = 3
    }

    [Theory]
    [InlineData(1, false)]
    [InlineData(2, true)]
    [InlineData(3, true)]
    public void HasPreviousPage_TrueOnlyWhenPageIndexGreaterThan1(int pageIndex, bool expected)
    {
        var list = new PaginatedList<int>(new List<int>(), 30, pageIndex, 10);
        Assert.Equal(expected, list.HasPreviousPage);
    }

    [Theory]
    [InlineData(1, 3, true)]
    [InlineData(2, 3, true)]
    [InlineData(3, 3, false)]
    public void HasNextPage_TrueOnlyWhenPageIndexLessThanTotalPages(int pageIndex, int totalPages, bool expected)
    {
        // count = totalPages * pageSize to get exact totalPages
        var list = new PaginatedList<int>(new List<int>(), totalPages * 10, pageIndex, 10);
        Assert.Equal(expected, list.HasNextPage);
    }

    [Fact]
    public void Create_ReturnsCorrectPage()
    {
        // Arrange — 25 items, page 2, page size 10 → items 11-20
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(10, result.Count);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_HasCorrectCount()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(5, result.Count);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
        Assert.True(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_FirstPage_HasNoPreviousPage()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.False(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
        Assert.Equal(10, result.Count);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_SinglePage_NoNextOrPrevious()
    {
        var source = Enumerable.Range(1, 5).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }
}

