using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First(s => s.LastName == "Student");
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void CanAddAndRetrieveInstructor()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Instructor",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.First(i => i.LastName == "Instructor");
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2020, 1, 1), retrieved.HireDate);
    }

    [Fact]
    public void CanAddAndRetrieveDepartment()
    {
        var dept = new Department
        {
            Name = "TestDept",
            Budget = 100000m,
            StartDate = new DateTime(2020, 9, 1)
        };

        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.First(d => d.Name == "TestDept");
        Assert.Equal(100000m, retrieved.Budget);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var dept = new Department { Name = "Dept", Budget = 1000m, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = 5000,
            Title = "TestCourse",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.First(c => c.CourseID == 5000);
        Assert.Equal("TestCourse", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
        Assert.Equal(dept.DepartmentID, retrieved.DepartmentID);
    }

    [Fact]
    public void CanAddAndRetrieveEnrollment()
    {
        var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var dept = new Department { Name = "D", Budget = 1000m, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 6000, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.A
        };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.First(e => e.StudentID == student.ID && e.CourseID == course.CourseID);
        Assert.Equal(Grade.A, retrieved.Grade);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        var instructor = new Instructor { FirstMidName = "I", LastName = "Test", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        var dept = new Department { Name = "D", Budget = 1000m, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 7000, Title = "T", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.First(x => x.InstructorID == instructor.ID && x.CourseID == course.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
    }

    [Fact]
    public void OfficeAssignment_LinkedToInstructor()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Office",
            LastName = "Test",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.LastName == "Test");
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Notification_CanBeStoredAndRetrieved()
    {
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test notification",
            CreatedAt = DateTime.Now,
            CreatedBy = "System",
            IsRead = false
        };

        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("1", retrieved.EntityId);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.Equal("Test notification", retrieved.Message);
        Assert.False(retrieved.IsRead);
    }

    [Fact]
    public void DbSets_AreExposed()
    {
        Assert.NotNull(_context.Courses);
        Assert.NotNull(_context.Enrollments);
        Assert.NotNull(_context.Departments);
        Assert.NotNull(_context.OfficeAssignments);
        Assert.NotNull(_context.CourseAssignments);
        Assert.NotNull(_context.People);
        Assert.NotNull(_context.Students);
        Assert.NotNull(_context.Instructors);
        Assert.NotNull(_context.Notifications);
    }
}

