+
+namespace ContosoUniversity.Tests;
+
+public class BaseControllerTests : IDisposable
+{
+    private readonly SchoolContext _context;
+    private readonly TestableBaseController _controller;
+
+    public BaseControllerTests()
+    {
+        _context = TestDbContextFactory.Create();
+        _controller = new TestableBaseController(_context);
+    }
+
+    public void Dispose()
+    {
+        _controller.Dispose();
+        _context.Dispose();
+    }
+
+    [Fact]
+    public void SendEntityNotification_WithDisplayName_DoesNotThrow()
+    {
+        var exception = Record.Exception(() =>
+            _controller.CallSendEntityNotification("Student", "1", "John Doe", EntityOperation.CREATE));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void SendEntityNotification_WithoutDisplayName_DoesNotThrow()
+    {
+        var exception = Record.Exception(() =>
+            _controller.CallSendEntityNotification("Student", "1", EntityOperation.CREATE));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void SendEntityNotification_ThreeParamOverload_CallsFourParamWithNullName()
+    {
+        // Should not throw and should still work
+        var exception = Record.Exception(() =>
+            _controller.CallSendEntityNotification("Instructor", "42", EntityOperation.UPDATE));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void Dispose_DoesNotThrow()
+    {
+        var ctx = TestDbContextFactory.Create();
+        var ctrl = new TestableBaseController(ctx);
+        var exception = Record.Exception(() => ctrl.Dispose());
+        Assert.Null(exception);
+    }
+
+    /// <summary>
+    /// Concrete subclass to test the abstract BaseController.
+    /// </summary>
+    private class TestableBaseController : BaseController
+    {
+        public TestableBaseController(SchoolContext context) : base(context) { }
+
+        public void CallSendEntityNotification(string entityType, string entityId, EntityOperation operation)
+        {
+            SendEntityNotification(entityType, entityId, operation);
+        }
+
+        public void CallSendEntityNotification(string entityType, string entityId, string? entityDisplayName, EntityOperation operation)
+        {
+            SendEntityNotification(entityType, entityId, entityDisplayName!, operation);
+        }
+    }
+}
